API Gateway / BFF.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway / BFF container

Container_Boundary(api_gateway_bff, "API Gateway / BFF") {
    Component(Edge Routing Controller, "Edge Routing Controller", "Envoy/Kong Router", "Handles reverse proxying, URL routing, and edge security for incoming traffic.")
    Component(Token Exchange & Auth Service, "Token Exchange & Auth Service", "OAuth2/OIDC Middleware", "Manages token exchange, user authentication, and multi-factor authentication validation.")
    Component(Payload Aggregator, "Payload Aggregator", "TypeScript/Node.js", "Aggregates responses to meet sub-second P95 performance targets for SPA clients.")
}

Rel(Edge Routing Controller, Token Exchange & Auth Service, "Authenticates requests")
Rel(Edge Routing Controller, Payload Aggregator, "Forwards routed requests")

@enduml

